/**
 * Dispatch pending weapon hit events to the main thread.
 * Called every physics frame.
 *
 * Events are dispatched via the 'physicEvent' pattern:
 * - Target: `${targetType}_hit_${targetIndex}` (e.g., "kinematic_hit_5")
 * - This maintains compatibility with the legacy rayshoot event system
 *
 * Hit event payload includes:
 * - shooterIndex, shooterType
 * - targetIndex, targetType
 * - hitPoint, hitNormal, distance
 * - weaponType ('hitscan', 'projectile', 'hybrid')
 * - damage
 * - projectileId, flightTime (for projectiles)
 * - isAoE, aoeCenter (for AoE hits)
 */
export function manageWeaponEvents(): void;
/**
 * Dispatch pending rayshoot hit events (legacy compatibility).
 * Routes legacy rayshoot hits through the new unified system.
 */
export function manageRayshootEventsCompat(): void;
